import hashlib


class Solver:
    def solve(self, problem, **kwargs):
        # hashlib and the cryptography reference both call OpenSSL's AVX2
        # SHA-256. The compression chain is serial, so this is the fast path
        # that still returns the reference digest.
        return {"digest": hashlib.sha256(problem["plaintext"]).digest()}

