static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }
static inline uint32_t bswap32(uint32_t x){
    return (x>>24)|((x>>8)&0xff00)|((x<<8)&0xff0000)|(x<<24);
}

/* Interleaved 4-way transform of 4 independent 64-byte blocks */
static void transform4(uint32_t S[4][8], const uint8_t *b0, const uint8_t *b1, const uint8_t *b2, const uint8_t *b3) {
    uint32_t W[4][64];
    const uint8_t *bs[4] = {b0,b1,b2,b3};
    for (int l=0;l<4;l++) {
        const uint32_t *src = (const uint32_t*)bs[l];
        for (int i=0;i<16;i++) W[l][i] = bswap32(src[i]);
        for (int i=16;i<64;i++) {
            uint32_t x = W[l][i-15];
            uint32_t s0 = rotr(x,7)^rotr(x,18)^(x>>3);
            uint32_t y = W[l][i-2];
            uint32_t s1 = rotr(y,17)^rotr(y,19)^(y>>10);
            W[l][i] = W[l][i-16] + s0 + W[l][i-7] + s1;
        }
    }
    uint32_t a[4],b[4],c[4],d[4],e[4],f[4],g[4],h[4];
    for (int l=0;l<4;l++) {
        a[l]=S[l][0]; b[l]=S[l][1]; c[l]=S[l][2]; d[l]=S[l][3];
        e[l]=S[l][4]; f[l]=S[l][5]; g[l]=S[l][6]; h[l]=S[l][7];
    }
    for (int i=0;i<64;i++) {
        uint32_t ki = K[i];
        for (int l=0;l<4;l++) {
            uint32_t S1 = rotr(e[l],6)^rotr(e[l],11)^rotr(e[l],25);
            uint32_t ch = (e[l]&f[l])^((~e[l])&g[l]);
            uint32_t t1 = h[l] + S1 + ch + ki + W[l][i];
            uint32_t S0 = rotr(a[l],2)^rotr(a[l],13)^rotr(a[l],22);
            uint32_t maj = (a[l]&b[l])^(a[l]&c[l])^(b[l]&c[l]);
            uint32_t t2 = S0 + maj;
            h[l]=g[l]; g[l]=f[l]; f[l]=e[l]; e[l]=d[l]+t1; d[l]=c[l]; c[l]=b[l]; b[l]=a[l]; a[l]=t1+t2;
        }
    }
    for (int l=0;l<4;l++) {
        S[l][0]+=a[l]; S[l][1]+=b[l]; S[l][2]+=c[l]; S[l][3]+=d[l];
        S[l][4]+=e[l]; S[l][5]+=f[l]; S[l][6]+=g[l]; S[l][7]+=h[l];
    }
}

/* Hash 4 independent messages of equal length (multiple of 64, no padding handled - raw blocks only) */
void hash4_raw(const uint8_t *m0, const uint8_t *m1, const uint8_t *m2, const uint8_t *m3, size_t nblocks, uint32_t out[4][8]) {
    uint32_t S[4][8];
    for (int l=0;l<4;l++) {
        S[l][0]=0x6a09e667; S[l][1]=0xbb67ae85; S[l][2]=0x3c6ef372; S[l][3]=0xa54ff53a;
        S[l][4]=0x510e527f; S[l][5]=0x9b05688c; S[l][6]=0x1f83d9ab; S[l][7]=0x5be0cd19;
    }
    for (size_t i=0;i<nblocks;i++) {
