        SHA256_CTX c; SHA256_Init(&c); SHA256_Update(&c, buf+lane*n, n);
        int ok = 1;
        for (int w=0;w<8;w++) if (c.h[w] != ((uint32_t*)(region+w*0x20))[lane]) ok=0;
        printf("lane %d %s  mid=", lane, ok?"OK":"FAIL");
