#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>

typedef struct { const unsigned char *ptr; int blocks; int pad; } HASH_DESC;
extern void sha256_multi_block(void *ctx, HASH_DESC *descs, int num);
static const uint32_t IV[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};

#define MAXW 4
typedef struct {
    pthread_mutex_t mu;
    pthread_cond_t cv_work, cv_done;
    int nworkers;
    int phase;          /* incremented to dispatch */
    int seen[MAXW];
    int done_count;
    int stop;
    unsigned char *regions[MAXW];
    HASH_DESC descs[MAXW][8];
} Pool;

static Pool pool;

static void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    int local_phase = 0;
    while (1) {
        pthread_mutex_lock(&pool.mu);
        while (pool.phase == local_phase && !pool.stop)
            pthread_cond_wait(&pool.cv_work, &pool.mu);
        if (pool.stop) { pthread_mutex_unlock(&pool.mu); break; }
        local_phase = pool.phase;
        pthread_mutex_unlock(&pool.mu);

        unsigned char *region = pool.regions[id];
        memset(region, 0, 0x100);
        for (int w=0; w<8; w++) {
            uint32_t *p = (uint32_t*)(region + w*0x20);
            for (int lane=0; lane<8; lane++) p[lane] = IV[w];
        }
        sha256_multi_block(region, pool.descs[id], 2);

        pthread_mutex_lock(&pool.mu);
        pool.done_count++;
        if (pool.done_count == pool.nworkers)
            pthread_cond_signal(&pool.cv_done);
        pthread_mutex_unlock(&pool.mu);
    }
    return NULL;
}

static void pool_init(int n) {
    memset(&pool, 0, sizeof(pool));
    pthread_mutex_init(&pool.mu, NULL);
    pthread_cond_init(&pool.cv_work, NULL);
    pthread_cond_init(&pool.cv_done, NULL);
    pool.nworkers = n;
    for (int i=0;i<n;i++) pool.regions[i] = aligned_alloc(64, 512);
    for (int i=0;i<n;i++) {
        pthread_t th;
        pthread_create(&th, NULL, worker, (void*)(intptr_t)i);
        pthread_detach(th);
    }
}

static void pool_run(void) {
    pthread_mutex_lock(&pool.mu);
    pool.done_count = 0;
    pool.phase++;
    pthread_cond_broadcast(&pool.cv_work);
    while (pool.done_count < pool.nworkers)
        pthread_cond_wait(&pool.cv_done, &pool.mu);
    pthread_mutex_unlock(&pool.mu);
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec/1e9;
}

int main(int argc, char **argv) {
    int nworkers = argc>1 ? atoi(argv[1]) : 2;
    pool_init(nworkers);
    size_t total = 20*1024*1024ull;
    int lanes = 8 * nworkers;
    size_t each = total / lanes;
    each = (each/64)*64;
    int blocks = (int)(each/64);
    unsigned char *buf = malloc(each*lanes + 64);
    memset(buf, 0x61, each*lanes);
    for (int t=0;t<nworkers;t++) {
        for (int i=0;i<8;i++) {
            pool.descs[t][i].ptr = buf + (size_t)(t*8+i)*each;
            pool.descs[t][i].blocks = blocks;
            pool.descs[t][i].pad = 0;
        }
    }
    pool_run(); /* warmup */
    int iters = 10;
    double t0 = now();
    for (int it=0; it<iters; it++) {
        /* reset descs (function may not modify them, but be safe) */
        for (int t=0;t<nworkers;t++)
            for (int i=0;i<8;i++) {
                pool.descs[t][i].ptr = buf + (size_t)(t*8+i)*each;
                pool.descs[t][i].blocks = blocks;
            }
        pool_run();
    }
    double t1 = now();
    double bytes = (double)each * lanes * iters;
    printf("%d workers: %.4f s/iter for %.2f MB => %.1f MB/s\n",
           nworkers, (t1-t0)/iters, (each*lanes)/1e6, (bytes/1e6)/(t1-t0));
    return 0;
}
EOF
