{"command":"cat > parallel_sha.c << 'EOF'
/*
 * Correct parallel SHA-256 via length-extension / midstate continuation.
 *
 * Split message into N chunks (each a multiple of 64 except possibly the last).
 * Thread 0 hashes chunk 0 from IV, producing midstate M0 (and the running length).
 * Thread k>0 hashes chunk k as if it were a continuation: we need M_{k-1} which
 * we don't have yet. So this only works sequentially. This file documents that
 * and instead times the SEQUENTIAL continuation to confirm correctness, plus a
 * parallel INDEPENDENT hash for speed reference.
 *
 * The useful experiment: how fast can N threads compute the chain if we pipeline
 * at block granularity? That's still serial for the state. Skip.
 *
 * REAL experiment: use OpenSSL multi-block to compute 8 independent chunk hashes
 * and also the true hash, and print both times, so we know the gap.
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/sha.h>

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9;}

typedef struct { unsigned char *data; size_t len; unsigned char out[32]; } Job;
static void *run(void *p){ Job*j=p; SHA256(j->data, j->len, j->out); return NULL; }

int main() {
    size_t n = 8*1024*1024;
    unsigned char *buf = malloc(n);
    memset(buf, 'a', n);
    unsigned char out[32];

    double t0=now();
    for(int i=0;i<3;i++) SHA256(buf, n, out);
    double t1=now();
    printf("serial SHA256: %.4f s  %.0f MB/s\n", (t1-t0)/3, (n/1e6)/((t1-t0)/3));

    /* 4 threads each hashing 2MB independent — upper bound if the problem were parallel */
    int nt=4;
    size_t chunk=n/nt;
    Job jobs[4];
    pthread_t th[4];
    for(int i=0;i<nt;i++){ jobs[i].data=buf+i*chunk; jobs[i].len=chunk; }
    t0=now();
    for(int it=0;it<3;it++){
        for(int i=0;i<nt;i++) pthread_create(&th[i], NULL, run, &jobs[i]);
        for(int i=0;i<nt;i++) pthread_join(th[i], NULL);
    }
    t1=now();
    printf("4-thread independent: %.4f s  %.0f MB/s\n", (t1-t0)/3, (n/1e6)/((t1-t0)/3));
    return 0;
}
EOF
