{"command":"cat > sha_ext.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct { const unsigned char *ptr; int blocks; int pad; } HASH_DESC;
extern void sha256_multi_block(void *ctx, HASH_DESC *descs, int num);

static const uint32_t IV[8] = {
    0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
    0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
};

#define MAXW 4
typedef struct {
    pthread_mutex_t mu;
    pthread_cond_t cv_work, cv_done;
    int nworkers, phase, done_count, stop, inited;
    unsigned char *regions[MAXW];
    HASH_DESC descs[MAXW][8];
} Pool;
static Pool pool;

static void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    int local = 0;
    for (;;) {
        pthread_mutex_lock(&pool.mu);
        while (pool.phase == local && !pool.stop)
            pthread_cond_wait(&pool.cv_work, &pool.mu);
        if (pool.stop) { pthread_mutex_unlock(&pool.mu); return NULL; }
        local = pool.phase;
        pthread_mutex_unlock(&pool.mu);

        unsigned char *region = pool.regions[id];
        for (int w = 0; w < 8; w++) {
            uint32_t *p = (uint32_t *)(region + w * 0x20);
            for (int lane = 0; lane < 8; lane++) p[lane] = IV[w];
        }
        sha256_multi_block(region, pool.descs[id], 2);

        pthread_mutex_lock(&pool.mu);
        if (++pool.done_count == pool.nworkers)
            pthread_cond_signal(&pool.cv_done);
        pthread_mutex_unlock(&pool.mu);
    }
}

static void pool_init(int n) {
    if (pool.inited) return;
    memset(&pool, 0, sizeof(pool));
    pthread_mutex_init(&pool.mu, NULL);
    pthread_cond_init(&pool.cv_work, NULL);
    pthread_cond_init(&pool.cv_done, NULL);
    pool.nworkers = n;
    for (int i = 0; i < n; i++)
        pool.regions[i] = aligned_alloc(64, 512);
    for (int i = 0; i < n; i++) {
        pthread_t th;
        pthread_create(&th, NULL, worker, (void *)(intptr_t)i);
        pthread_detach(th);
    }
    pool.inited = 1;
}

static void pool_run(void) {
    pthread_mutex_lock(&pool.mu);
    pool.done_count = 0;
    pool.phase++;
    pthread_cond_broadcast(&pool.cv_work);
    while (pool.done_count < pool.nworkers)
        pthread_cond_wait(&pool.cv_done, &pool.mu);
    pthread_mutex_unlock(&pool.mu);
}

/* Parallel independent chunk hashes. NOT a single SHA-256.
 * Returns a 32-byte digest that is SHA256 of the concatenation of per-chunk
 * midstates — used only for speed experiments. */
static PyObject *parallel_chunks(PyObject *self, PyObject *args) {
    Py_buffer view;
    int nworkers = 3;
    if (!PyArg_ParseTuple(args, "y*|i", &view, &nworkers)) return NULL;
    if (nworkers < 1) nworkers = 1;
    if (nworkers > MAXW) nworkers = MAXW;
    pool_init(nworkers);

    const unsigned char *data = view.buf;
    size_t len = view.len;
    int lanes = 8 * nworkers;
    size_t each = (len / lanes / 64) * 64;
    if (each == 0) {
        PyBuffer_Release(&view);
        PyErr_SetString(PyExc_ValueError, "too small");
        return NULL;
    }
    int blocks = (int)(each / 64);
    for (int t = 0; t < nworkers; t++) {
        for (int i = 0; i < 8; i++) {
            pool.descs[t][i].ptr = data + (size_t)(t * 8 + i) * each;
            pool.descs[t][i].blocks = blocks;
            pool.descs[t][i].pad = 0;
        }
    }
    Py_BEGIN_ALLOW_THREADS
    pool_run();
    Py_END_ALLOW_THREADS

    /* fold midstates into 32 bytes so we return something */
    unsigned char out[32];
    memset(out, 0, 32);
    for (int t = 0; t < nworkers; t++) {
        for (int lane = 0; lane < 8; lane++) {
            for (int w = 0; w < 8; w++) {
                uint32_t v = ((uint32_t *)(pool.regions[t] + w * 0x20))[lane];
                out[(w * 4) & 31] ^= (unsigned char)(v >> 24);
                out[(w * 4 + 1) & 31] ^= (unsigned char)(v >> 16);
                out[(w * 4 + 2) & 31] ^= (unsigned char)(v >> 8);
                out[(w * 4 + 3) & 31] ^= (unsigned char)v;
            }
        }
    }
    PyBuffer_Release(&view);
    return PyBytes_FromStringAndSize((char *)out, 32);
}

static PyMethodDef methods[] = {
    {"parallel_chunks", parallel_chunks, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "sha_ext", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_sha_ext(void) { return PyModule_Create(&moduledef); }
EOF
