static PyObject *sha256_fast(PyObject *self, PyObject *args) {
    Py_buffer view;
    if (!PyArg_ParseTuple(args, "y*", &view))
        return NULL;

    const unsigned char *data = (const unsigned char *)view.buf;
    size_t len = (size_t)view.len;
    size_t nblocks = len >> 6;
    size_t rem = len & 63;

    SHA256_CTX c;
    SHA256_Init(&c);

    Py_BEGIN_ALLOW_THREADS
    if (nblocks)
        sha256_block_data_order(&c, data, nblocks);
    /* manual padding using one or two final transforms via SHA256_Update of the tail only.
       SHA256_Update would re-process nothing if we set Nl/Nh correctly and call Final.
       Easiest correct path: SHA256_Update the remainder then Final, but Nl must include
       the blocks already consumed. sha256_block_data_order does NOT update Nl/Nh.
       So set them. */
    c.Nl = (uint32_t)(len << 3);
    c.Nh = (uint32_t)(len >> 29);
    c.num = 0;
    Py_END_ALLOW_THREADS

    if (rem) {
        memcpy(c.data, data + (nblocks << 6), rem);
        c.num = (unsigned int)rem;
    }
    unsigned char out[32];
    SHA256_Final(out, &c);

    PyBuffer_Release(&view);
    return PyBytes_FromStringAndSize((char *)out, 32);
}

